423	function sessionReadinessFailure(snapshot: SessionNextData, inputSessionId: string): string | null {
424	  if (snapshot.contract_version !== 3) {
425	    return `unsupported_session_next_contract:${snapshot.contract_version}`;
426	  }
427	  if (snapshot.session_id !== inputSessionId) {
428	    return 'session_id_mismatch';
429	  }
430	  if (
431	    snapshot.proof.status === 'migration_required' ||
432	    snapshot.staleness.status === 'migration_required' ||
433	    snapshot.repair_budget.status === 'migration_required' ||
434	    snapshot.audit.status === 'migration_required'
435	  ) {
436	    return 'migration_required';
437	  }
438	  if (snapshot.audit.status !== 'valid') {
439	    return `audit_not_valid:${snapshot.audit.status}`;
440	  }
441	  return null;
442	}
