444	function wakeProjectionValidationFailure(snapshot: SessionNextData, context: WakeProjectionContext): string | null {
445	  if (context.git.repoRoot !== context.inputRepoRoot) {
446	    return 'git_root_mismatch';
447	  }
448	  if (!context.git.worktreeClean) {
449	    return 'git_worktree_not_clean';
450	  }
451	  if (snapshot.contract_version !== 3) {
452	    return `unsupported_session_next_contract:${snapshot.contract_version}`;
453	  }
454	  if (
455	    snapshot.session_id !== context.inputSessionId ||
456	    context.status.session_id !== context.inputSessionId ||
457	    context.status.session.id !== context.inputSessionId
458	  ) {
459	    return 'session_id_mismatch';
460	  }
461	  if (
462	    snapshot.task_id !== context.status.task_id ||
463	    context.status.task.id !== context.status.task_id ||
464	    snapshot.lifecycle.state !== context.status.task.status ||
465	    snapshot.lifecycle.state_version !== context.status.task.state_version
466	  ) {
467	    return 'session_status_mismatch';
468	  }
469	  if (context.status.task.title.trim().length === 0 || context.status.task.goal.trim().length === 0) {
470	    return 'session_task_scope_missing';
471	  }
472	  if (
473	    snapshot.repository.branch !== context.git.branch ||
474	    snapshot.repository.head_sha !== context.git.headSha ||
475	    snapshot.repository.worktree.clean !== context.git.worktreeClean
476	  ) {
477	    return 'repository_snapshot_mismatch';
478	  }
479	  if (!proofStatuses.has(snapshot.proof.status)) {
480	    return `unknown_proof_status:${snapshot.proof.status}`;
481	  }
482	  if (snapshot.proof.status === 'migration_required') {
483	    return 'migration_required:proof';
484	  }
485	  const unknownProofGate = snapshot.proof.gates.find(({ status }) => !proofGateStatuses.has(status));
486	  if (unknownProofGate) {
487	    return `unknown_proof_gate_status:${unknownProofGate.status}`;
488	  }
489	  if (!ciProofStatuses.has(snapshot.ci_proof.status)) {
490	    return `unknown_ci_proof_status:${snapshot.ci_proof.status}`;
491	  }
492	  const unknownCiGate = snapshot.ci_proof.gates.find(({ status }) => !ciProofGateStatuses.has(status));
493	  if (unknownCiGate) {
