function sessionReadinessFailure(snapshot: SessionNextData, inputSessionId: string): string | null {
  if (snapshot.contract_version !== 3) {
    return `unsupported_session_next_contract:${snapshot.contract_version}`;
  }
  if (snapshot.session_id !== inputSessionId) {
    return 'session_id_mismatch';
  }
  if (
    snapshot.proof.status === 'migration_required' ||
    snapshot.staleness.status === 'migration_required' ||
    snapshot.repair_budget.status === 'migration_required' ||
    snapshot.audit.status === 'migration_required'
  ) {
    return 'migration_required';
  }
  if (snapshot.audit.status !== 'valid') {
    return `audit_not_valid:${snapshot.audit.status}`;
  }
  return null;
}

function wakeProjectionValidationFailure(snapshot: SessionNextData, context: WakeProjectionContext): string | null {
  if (context.git.repoRoot !== context.inputRepoRoot) {
    return 'git_root_mismatch';
  }
  if (!context.git.worktreeClean) {
    return 'git_worktree_not_clean';
  }
  if (snapshot.contract_version !== 3) {
    return `unsupported_session_next_contract:${snapshot.contract_version}`;
  }
