    snapshot.session_id !== context.inputSessionId ||
    context.status.session_id !== context.inputSessionId ||
    context.status.session.id !== context.inputSessionId
  ) {
    return 'session_id_mismatch';
  }
  if (
    snapshot.task_id !== context.status.task_id ||
    context.status.task.id !== context.status.task_id ||
    snapshot.lifecycle.state !== context.status.task.status ||
    snapshot.lifecycle.state_version !== context.status.task.state_version
  ) {
    return 'session_status_mismatch';
  }
  if (context.status.task.title.trim().length === 0 || context.status.task.goal.trim().length === 0) {
    return 'session_task_scope_missing';
  }
  if (
    snapshot.repository.branch !== context.git.branch ||
    snapshot.repository.head_sha !== context.git.headSha ||
    snapshot.repository.worktree.clean !== context.git.worktreeClean
  ) {
    return 'repository_snapshot_mismatch';
  }
  if (!proofStatuses.has(snapshot.proof.status)) {
    return `unknown_proof_status:${snapshot.proof.status}`;
  }
  if (snapshot.proof.status === 'migration_required') {
    return 'migration_required:proof';
  }
  const unknownProofGate = snapshot.proof.gates.find(({ status }) => !proofGateStatuses.has(status));
  if (unknownProofGate) {
    return `unknown_proof_gate_status:${unknownProofGate.status}`;
  }
  if (!ciProofStatuses.has(snapshot.ci_proof.status)) {
    return `unknown_ci_proof_status:${snapshot.ci_proof.status}`;
  }
  const unknownCiGate = snapshot.ci_proof.gates.find(({ status }) => !ciProofGateStatuses.has(status));
  if (unknownCiGate) {
    return `unknown_ci_proof_gate_status:${unknownCiGate.status}`;
  }
  if (!reviewStatuses.has(snapshot.review.status)) {
    return `unknown_review_status:${snapshot.review.status}`;
  }
  if (!stalenessStatuses.has(snapshot.staleness.status)) {
    return `unknown_staleness_status:${snapshot.staleness.status}`;
  }
  if (snapshot.staleness.status === 'migration_required') {
    return 'migration_required:staleness';
  }
  const expectedStaleness = ['missing', 'stale', 'corrupt'].includes(snapshot.proof.status)
    ? snapshot.proof.status
    : 'current';
