    (budget.attempts_used ?? 4) > 3 ||
    budget.remaining !== Math.max(0, 3 - (budget.attempts_used ?? 0)) ||
    budget.exhausted !== (budget.attempts_used ?? 0) >= 3 ||
    budget.status !== (budget.exhausted ? 'exhausted' : 'available')
  ) {
    return 'repair_budget_inconsistent';
  }
  if (snapshot.audit.status !== 'valid') {
    return `audit_not_valid:${snapshot.audit.status}`;
  }
  if (!terminalReasons.has(snapshot.terminal_reason)) {
    return `unknown_terminal_reason:${String(snapshot.terminal_reason)}`;
  }
  const expectedTerminalReason =
    snapshot.lifecycle.state === 'blocked'
      ? 'BLOCKED_REQUIRES_HUMAN_RECOVERY'
      : snapshot.lifecycle.state === 'completed'
        ? 'COMPLETED'
        : null;
  if (snapshot.terminal_reason !== expectedTerminalReason) {
    return 'terminal_reason_inconsistent';
  }

  const nextHumanAction = snapshot.next_human_action;
  if (nextHumanAction) {
    const requiredWork = snapshot.required_work[0];
    const matchesRequiredWork =
      snapshot.required_work.length === 1 &&
      requiredWork?.code === nextHumanAction.code &&
      requiredWork.description === nextHumanAction.description;
    const advancesToHuman =
      nextHumanAction.code === 'ADVANCE_TO_HUMAN_AUTHORITY' &&
      nextHumanAction.description.trim().length > 0 &&
      snapshot.lifecycle.state === 'reviewing' &&
      snapshot.candidate?.from_state === 'reviewing' &&
      snapshot.candidate.target_state === 'ready_for_human' &&
      snapshot.candidate.executable;
    if (!matchesRequiredWork && !advancesToHuman) {
      return `invalid_next_human_action:${nextHumanAction.code}`;
    }
  }
  return null;
}

