      return {
        decision: 'stop',
        actions: [],
        stopReason: `candidate_from_state_mismatch:${snapshot.candidate.from_state}->${snapshot.lifecycle.state}`,
      };
    }
    if (snapshot.candidate.expected_state_version !== snapshot.lifecycle.state_version) {
      return {
        decision: 'stop',
        actions: [],
        stopReason: `candidate_state_version_mismatch:${snapshot.candidate.expected_state_version}->${snapshot.lifecycle.state_version}`,
      };
    }
  }
  if (snapshot.lifecycle.state === 'ready_for_human') {
    return { decision: 'stop', actions: [], stopReason: 'hard_stop:ready_for_human' };
  }
  if (snapshot.lifecycle.state === 'blocked') {
    return { decision: 'stop', actions: [], stopReason: 'hard_stop:blocked' };
  }
  if (snapshot.repair_budget.status === 'exhausted' || snapshot.repair_budget.exhausted === true) {
    return { decision: 'stop', actions: [], stopReason: 'hard_stop:repair_budget_exhausted' };
  }
  if (snapshot.lifecycle.state === 'completed') {
    return { decision: 'stop', actions: [], stopReason: 'hard_stop:completed' };
  }
  if (snapshot.candidate?.target_state === 'blocked' || snapshot.candidate?.target_state === 'completed') {
    return { decision: 'stop', actions: [], stopReason: `forbidden_target:${snapshot.candidate.target_state}` };
  }
  if (snapshot.candidate?.executable) {
    if (snapshot.guard_failures.length > 0 || snapshot.required_work.length > 0) {
      return { decision: 'stop', actions: [], stopReason: 'candidate_contract_inconsistent' };
    }
    const action: WakeAction = {
      kind: 'transition',
      codeOrTarget: snapshot.candidate.target_state,
    };
    return { decision: action.kind, actions: [action], stopReason: null };
  }
  if (snapshot.required_work.length !== 1) {
    return { decision: 'stop', actions: [], stopReason: 'required_work_unavailable_or_ambiguous' };
  }

  const code = snapshot.required_work[0]?.code ?? '';
  const knownWork =
    repositoryWorkCodes.has(code) ||
    localGateCodes.has(code) ||
    signedEvidenceCodes.has(code) ||
    stopOnlyWorkCodes.has(code);
  if (!knownWork) {
    return { decision: 'stop', actions: [], stopReason: `unknown_required_work:${code}` };
  }
  const guardCode = snapshot.guard_failures[0]?.code ?? 'none';
  if (snapshot.guard_failures.length !== 1 || guardWorkPairs.get(guardCode) !== code) {
    return {
      decision: 'stop',
      actions: [],
      stopReason: `guard_work_pair_mismatch:${guardCode}->${code}`,
    };
  }
  if (repositoryWorkCodes.has(code)) {
    const action: WakeAction = { kind: 'repository_work', codeOrTarget: code };
    return { decision: action.kind, actions: [action], stopReason: null };
  }
  if (localGateCodes.has(code)) {
    const action: WakeAction = { kind: 'local_gate', codeOrTarget: code };
    return { decision: action.kind, actions: [action], stopReason: null };
  }
  if (signedEvidenceCodes.has(code)) {
    const action: WakeAction = { kind: 'signed_evidence', codeOrTarget: code };
    return { decision: action.kind, actions: [action], stopReason: null };
  }
  if (stopOnlyWorkCodes.has(code)) {
    return { decision: 'stop', actions: [], stopReason: `human_authority:${code}` };
  }
  return { decision: 'stop', actions: [], stopReason: 'unreachable_work_classification' };
}

function decideValidatedWake(snapshot: SessionNextData, context: WakeProjectionContext) {
  const validationFailure = wakeProjectionValidationFailure(snapshot, context);
  return validationFailure
    ? stopDecision(`invalid_projection:${validationFailure}`)
    : selectOneWakeActionFromValidatedProjection(snapshot);
}

function retainedTransitionGitSnapshotMatches(retained: GitWakeSnapshot, fresh: GitWakeSnapshot) {
  return (
    retained.repoRoot === fresh.repoRoot &&
    retained.branch === fresh.branch &&
    retained.headSha === fresh.headSha &&
    retained.worktreeClean === true &&
    fresh.worktreeClean === true
  );
}

