async function commitReplayFiles(replay: ReplaySession, message: string, files: Record<string, string>) {
  for (const [relativePath, contents] of Object.entries(files)) {
    const outputPath = path.join(replay.repoDir, relativePath);
    await mkdir(path.dirname(outputPath), { recursive: true });
    await writeFile(outputPath, contents, 'utf8');
  }
  await runObservedSubprocess(replay.repoDir, 'git', ['add', ...Object.keys(files)]);
  await runObservedSubprocess(replay.repoDir, 'git', ['commit', '-m', message]);
  replay.currentHead = (await runObservedSubprocess(replay.repoDir, 'git', ['rev-parse', 'HEAD'])).stdout.trim();
  return replay.currentHead;
}

