    canonicalJson({
      media_type: SIGNED_REVIEW_RECEIPT_MEDIA_TYPE,
      artifact,
      bundle: testSigstoreBundle(REVIEW_IN_TOTO_PAYLOAD_TYPE, statement),
    }),
    'utf8',
  );
  return packagePath;
}

