async function observeGitWakeSnapshot(repoRoot: string): Promise<GitWakeSnapshot> {
  const canonicalRoot = (
    await runObservedSubprocess(repoRoot, 'git', ['-C', repoRoot, 'rev-parse', '--show-toplevel'])
  ).stdout.trim();
  const branch = (
    await runObservedSubprocess(repoRoot, 'git', ['-C', repoRoot, 'symbolic-ref', '--quiet', '--short', 'HEAD'])
  ).stdout.trim();
  const headSha = (
    await runObservedSubprocess(repoRoot, 'git', [
      '-C',
      repoRoot,
      'rev-parse',
      '--verify',
      '--end-of-options',
      'HEAD^{commit}',
    ])
  ).stdout.trim();
  const status = await runObservedSubprocess(repoRoot, 'git', [
    '-C',
    repoRoot,
    '--no-optional-locks',
    'status',
    '--porcelain=v1',
    '-z',
    '--untracked-files=all',
    '--ignore-submodules=none',
  ]);
  return {
    repoRoot: canonicalRoot,
    branch,
    headSha,
    worktreeClean: status.stdout.length === 0,
  };
}

