function transitionEvents(audit: AuditShow) {
  return audit.events.filter(({ event }) => event.event_type === 'transition_applied');
}

function guardFailures(audit: AuditShow, code: string) {
  return audit.events.filter(({ event }) => {
    if (event.event_type !== 'guard_decision') {
      return false;
    }
    const error = event.payload.error;
    return typeof error === 'object' && error !== null && (error as { code?: unknown }).code === code;
  });
}

function expectRequiredWorkBoundary(
  next: SuccessEnvelope<SessionNextData>,
  guardCode: string,
  workCode: string,
  decisionKind: Exclude<WakeAction['kind'], 'transition'>,
) {
  expect(next.data).toMatchObject({
    contract_version: 3,
    guard_failures: [{ code: guardCode }],
    required_work: [{ code: workCode }],
    audit: { status: 'valid' },
  });
  expect(next.data.candidate?.executable ?? false).toBe(false);
  const decision = selectOneWakeActionFromValidatedProjection(next.data);
  expect(decision).toEqual({
    decision: decisionKind,
    actions: [{ kind: decisionKind, codeOrTarget: workCode }],
    stopReason: null,
  });
  expect(decision.actions).toHaveLength(1);
  expect(decision.actions[0]?.kind).not.toBe('transition');
}

function verifyPinnedSourceLineage(fixture: ReplayFixture) {
  expect(fixture.source_lineage.object_type).toBe('commit');
  const commits = new Map(fixture.source_lineage.commits.map((commit) => [commit.role, commit]));
  for (const commit of fixture.source_lineage.commits) {
    const payload = Buffer.from(commit.payload, 'utf8');
    const framed = Buffer.concat([Buffer.from(`commit ${payload.byteLength}\0`, 'utf8'), payload]);
    expect(createHash('sha1').update(framed).digest('hex')).toBe(commit.sha1);
  }

  const base = commits.get('base');
  const initial = commits.get('initial');
  const repair = commits.get('repair');
  expect(base?.sha1).toBe(fixture.base_head_sha);
  expect(initial?.sha1).toBe(fixture.initial_head_sha);
  expect(repair?.sha1).toBe(fixture.repair_head_sha);
  expect(commitParents(initial?.payload ?? '')).toEqual([fixture.base_head_sha]);
  expect(commitParents(repair?.payload ?? '')).toEqual([fixture.initial_head_sha]);
}

function commitParents(payload: string) {
  return [...payload.matchAll(/^parent ([a-f0-9]{40})$/gm)].map((match) => match[1]);
}

async function bindControllerProofPlan(
  setup: Awaited<ReturnType<typeof makeReplayRepository>>,
  idempotencyKey: string,
) {
  expect(idempotencyKey.startsWith('runner:v1:')).toBe(false);
  const gate = { ...setup.fixture.gate, timeout_ms: 5_000 };
  const result = await transitionLifecycle(setup.repoDir, setup.sessionId, 'proof_ready', 1, idempotencyKey, {
    proof_plan: replayProofPlan(setup.fixture, gate),
  });
  expect(result.data.idempotency_key).toBe(idempotencyKey);
  if (!result.data.proof_plan) {
    throw new Error('The replay proof plan was not persisted.');
  }
  return {
    ...setup,
    planSha256: result.data.proof_plan.sha256,
    gate,
    currentHead: setup.baselineHead,
  } satisfies ReplaySession;
}

async function beginReplayWake(
  replay: ReplaySession | Awaited<ReturnType<typeof makeReplayRepository>>,
  traces: WakeTrace[],
  wakeId: string,
) {
  expect(wakeId).toMatch(/^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/);
  expect(traces.some((trace) => trace.wakeId === wakeId)).toBe(false);
  const git = await observeGitWakeSnapshot(replay.repoDir);
  const readable = await sessionNext(replay.repoDir, replay.sessionId);
  const readinessFailure = sessionReadinessFailure(readable.data, replay.sessionId);
  if (readinessFailure) {
    const trace: WakeTrace = {
      wakeId,
      snapshot: {
        git,
        lifecycleState: readable.data.lifecycle.state,
        stateVersion: readable.data.lifecycle.state_version,
        auditRoot: readable.data.audit.root,
      },
      decision: stopDecision(`invalid_readiness:${readinessFailure}`),
      actionsStarted: [],
      stopped: false,
    };
    traces.push(trace);
    return { next: readable, trace };
  }
  const status = await sessionStatus(replay.repoDir, replay.sessionId);
  const next = await sessionNext(replay.repoDir, replay.sessionId);
  const context: WakeProjectionContext = {
    inputRepoRoot: replay.repoDir,
    inputSessionId: replay.sessionId,
    git,
    status: status.data,
  };
  const decision = decideValidatedWake(next.data, context);
  expect(decision.actions.length).toBeLessThanOrEqual(1);
  const trace: WakeTrace = {
    wakeId,
    snapshot: {
      git,
      lifecycleState: next.data.lifecycle.state,
      stateVersion: next.data.lifecycle.state_version,
      auditRoot: next.data.audit.root,
    },
    decision,
    actionsStarted: [],
    stopped: false,
  };
  traces.push(trace);
  return { next, trace, context };
}

async function performWakeAction<T>(trace: WakeTrace, expectedAction: WakeAction, action: () => Promise<T>) {
  expect(trace.decision).toEqual({
    decision: expectedAction.kind,
    actions: [expectedAction],
    stopReason: null,
  });
  expect(trace.actionsStarted).toHaveLength(0);
  trace.actionsStarted.push(expectedAction);
  try {
    return await action();
  } finally {
    trace.stopped = true;
  }
}

