async function runRepositoryWake<T>(
  replay: ReplaySession,
  traces: WakeTrace[],
  wakeId: string,
  workCode: string,
  action: () => Promise<T>,
) {
  const { next, trace } = await beginReplayWake(replay, traces, wakeId);
  const result = await performWakeAction(trace, { kind: 'repository_work', codeOrTarget: workCode }, action);
  return { next, result, trace };
}

async function runGateWake(replay: ReplaySession, traces: WakeTrace[], wakeId: string, workCode: string) {
  const { next, trace } = await beginReplayWake(replay, traces, wakeId);
  const result = await performWakeAction(trace, { kind: 'local_gate', codeOrTarget: workCode }, async () =>
    parseJson<SuccessEnvelope<GateRunData>>(
      (
        await runCli(replay.repoDir, [
          'session',
          'gate',
          'run',
          replay.fixture.gate.id,
          '--session',
          replay.sessionId,
          '--json',
        ])
      ).stdout,
    ),
  );
  return { next, result, trace };
}

async function runEvidenceWake<T>(
  replay: ReplaySession,
  traces: WakeTrace[],
  wakeId: string,
  workCode: string,
  action: () => Promise<T>,
) {
  const { next, trace } = await beginReplayWake(replay, traces, wakeId);
  const result = await performWakeAction(trace, { kind: 'signed_evidence', codeOrTarget: workCode }, action);
  return { next, result, trace };
}

async function runStopWake(replay: ReplaySession, traces: WakeTrace[], wakeId: string, expectedReason: string) {
  const { next, trace } = await beginReplayWake(replay, traces, wakeId);
  expect(trace.decision).toEqual({ decision: 'stop', actions: [], stopReason: expectedReason });
  trace.stopped = true;
  return { next, trace };
}

function expectWakeTraceInvariants(traces: WakeTrace[]) {
  expect(new Set(traces.map((trace) => trace.wakeId)).size).toBe(traces.length);
  expect(traces.every((trace) => trace.stopped)).toBe(true);
  expect(traces.every((trace) => trace.actionsStarted.length <= 1)).toBe(true);
  for (const trace of traces) {
    expect(trace.snapshot.git.repoRoot).toMatch(/^[/]/);
    expect(trace.snapshot.git.branch).not.toBe('');
    expect(trace.snapshot.git.headSha).toMatch(/^[a-f0-9]{40}$/);
    expect(trace.snapshot.git.worktreeClean).toBe(true);
  }
  for (const trace of traces.filter(({ decision }) => decision.decision === 'transition')) {
    expect(trace.actionsStarted).toHaveLength(1);
    expect(trace.actionsStarted[0]?.kind).toBe('transition');
  }
}

function expectNoForbiddenAuthorityCommands(commands: ObservedCommand[], forbiddenActions: string[]) {
  expect(commands.length).toBeGreaterThan(0);
  expect(commands.some(({ executable, args }) => executable === 'git' && args[0] === 'commit')).toBe(true);
  expect(
    commands.some(
      ({ executable, args }) => executable === 'node' && args.includes('session') && args.includes('transition'),
    ),
  ).toBe(true);

  const networkExecutables = new Set(['curl', 'ftp', 'nc', 'scp', 'sftp', 'ssh', 'wget']);
  for (const command of commands) {
    const executable = path.basename(command.executable).toLowerCase();
    expect(executable).not.toBe('gh');
    expect(networkExecutables.has(executable)).toBe(false);
    if (executable === 'git') {
      expect(['merge', 'push']).not.toContain(command.args[0]);
    }
    const normalized = [executable, ...command.args]
      .join(' ')
      .toLowerCase()
      .replaceAll(/[^a-z0-9]+/g, ' ');
    for (const action of forbiddenActions) {
      expect(normalized).not.toContain(action.toLowerCase().replaceAll(/[^a-z0-9]+/g, ' '));
    }
  }
}

