  it('fails closed when a public wake projection disagrees with independent preflight facts', async () => {
    const fixture = await loadReplayFixture();
    const replay = await makeReplayRepository(fixture);
    const git = await observeGitWakeSnapshot(replay.repoDir);
    const readable = await sessionNext(replay.repoDir, replay.sessionId);
    expect(sessionReadinessFailure(readable.data, replay.sessionId)).toBeNull();
    const status = await sessionStatus(replay.repoDir, replay.sessionId);
    const next = await sessionNext(replay.repoDir, replay.sessionId);
    const context: WakeProjectionContext = {
      inputRepoRoot: replay.repoDir,
      inputSessionId: replay.sessionId,
      git,
      status: status.data,
    };

    expect(wakeProjectionValidationFailure(next.data, context)).toBeNull();
    expect(decideValidatedWake(next.data, context)).toMatchObject({
      decision: 'transition',
      actions: [{ kind: 'transition', codeOrTarget: 'framed' }],
    });

    const invalidProjections: Array<[SessionNextData, string]> = [
      [
        (() => {
          const value = structuredClone(next.data);
          value.repository.branch = 'feat/other-work';
          return value;
        })(),
        'invalid_projection:repository_snapshot_mismatch',
      ],
      [
        (() => {
          const value = structuredClone(next.data);
          value.staleness.status = 'future';
          return value;
        })(),
        'invalid_projection:unknown_staleness_status:future',
      ],
      [
        (() => {
          const value = structuredClone(next.data);
          value.next_human_action = { code: 'FUTURE_HUMAN_ACTION', description: 'Unknown authority request' };
          return value;
        })(),
        'invalid_projection:invalid_next_human_action:FUTURE_HUMAN_ACTION',
      ],
      [
        (() => {
          const value = structuredClone(next.data);
          value.terminal_reason = 'FUTURE_TERMINAL_REASON';
          return value;
        })(),
        'invalid_projection:unknown_terminal_reason:FUTURE_TERMINAL_REASON',
      ],
    ];

    for (const [invalidProjection, stopReason] of invalidProjections) {
      const decision = decideValidatedWake(invalidProjection, context);
      expect(decision).toEqual({ decision: 'stop', actions: [], stopReason });
    }
  });

  it('deduplicates concurrent and lost-response retries, then durably projects a changed-request conflict', async () => {
    const { repoDir, sessionId } = await makeQueuedSession();
    const key = 'runner:v1:duplicate-001:0';
    const args = transitionArgs(sessionId, key);

    const [left, right] = await Promise.all([runCli(repoDir, args), runCli(repoDir, args)]);
    expect(right.stdout).toBe(left.stdout);

    const applied = parseJson<
      SuccessEnvelope<{
        contract_version: number;
        request_sha256: string;
        lifecycle: { state: string; state_version: number };
      }>
    >(left.stdout);
    expect(applied).toMatchObject({
      ok: true,
      command: 'session transition',
      data: {
        contract_version: 1,
        lifecycle: { state: 'framed', state_version: 1 },
      },
    });
    expect(applied.data.request_sha256).toMatch(/^[a-f0-9]{64}$/);

    const afterConcurrentWake = await auditShow(repoDir, sessionId);
    expect(afterConcurrentWake.data.contract_version).toBe(1);
    expect(afterConcurrentWake.data.verification.valid).toBe(true);
    expect(transitionEvents(afterConcurrentWake.data)).toHaveLength(1);

    const lostResponseRetry = await runCli(repoDir, args);
    expect(lostResponseRetry.stdout).toBe(left.stdout);
    const afterLostResponseRetry = await auditShow(repoDir, sessionId);
    expect(afterLostResponseRetry.data).toEqual(afterConcurrentWake.data);

    const conflict = parseJson<FailureEnvelope>(
      (await runCliFailure(repoDir, transitionArgs(sessionId, key, { retry_reason: 'changed request' }))).stderr,
    );
    expect(conflict).toMatchObject({
      ok: false,
      command: 'session transition',
      error: {
        code: 'IDEMPOTENCY_CONFLICT',
        details: {
          session_id: sessionId,
          idempotency_key: key,
          existing_request_sha256: applied.data.request_sha256,
        },
      },
    });
    const conflictingRequestSha = conflict.error.details?.request_sha256;
    expect(conflictingRequestSha).toMatch(/^[a-f0-9]{64}$/);
    expect(conflictingRequestSha).not.toBe(applied.data.request_sha256);

    const status = await sessionStatus(repoDir, sessionId);
    expect(status.data).toMatchObject({
      task: { status: 'framed', state_version: 1 },
      session: { ended_at: null },
    });

    const audit = await auditShow(repoDir, sessionId);
    expect(transitionEvents(audit.data)).toHaveLength(1);
    const conflicts = guardFailures(audit.data, 'IDEMPOTENCY_CONFLICT');
    expect(conflicts).toHaveLength(1);
    expect(conflicts[0]?.event.payload).toMatchObject({
      idempotency_key: key,
      request_sha256: conflictingRequestSha,
      error: {
        code: 'IDEMPOTENCY_CONFLICT',
        details: {
          request_sha256: conflictingRequestSha,
          existing_request_sha256: applied.data.request_sha256,
        },
      },
    });

    const next = await sessionNext(repoDir, sessionId);
    expect(next.data).toMatchObject({
      contract_version: 3,
      lifecycle: { state: 'framed', state_version: 1 },
      audit: { status: 'valid', event_count: audit.data.count, root: audit.data.root },
    });
    const verified = await auditVerify(repoDir, sessionId, audit.data.root);
    expect(verified.data).toMatchObject({
      contract_version: 1,
      session_id: sessionId,
      count: audit.data.count,
      root: audit.data.root,
      expected_root: audit.data.root,
      valid: true,
    });
  });

  it('allows one winner when distinct runner keys race at the same lifecycle version', async () => {
    const { repoDir, sessionId } = await makeQueuedSession();
    const race = await Promise.allSettled([
      runCli(repoDir, transitionArgs(sessionId, 'runner:v1:race-left:0')),
      runCli(repoDir, transitionArgs(sessionId, 'runner:v1:race-right:0')),
    ]);
    const successes = race.filter(
      (result): result is PromiseFulfilledResult<Awaited<ReturnType<typeof runCli>>> => result.status === 'fulfilled',
    );
    const failures = race.filter((result): result is PromiseRejectedResult => result.status === 'rejected');

    expect(successes).toHaveLength(1);
    expect(failures).toHaveLength(1);
    const winner = parseJson<
      SuccessEnvelope<{
        contract_version: number;
        lifecycle: { state: string; state_version: number };
      }>
    >(successes[0]?.value.stdout);
    expect(winner).toMatchObject({
      command: 'session transition',
      data: {
        contract_version: 1,
        lifecycle: { state: 'framed', state_version: 1 },
      },
    });

    const loser = parseJson<FailureEnvelope>((failures[0]?.reason as Error & { stderr?: string }).stderr);
    expect(loser).toMatchObject({
      command: 'session transition',
      error: {
        code: 'STATE_VERSION_CONFLICT',
        details: {
          session_id: sessionId,
          expected_state_version: 0,
          actual_state: 'framed',
          actual_state_version: 1,
        },
      },
    });

    const status = await sessionStatus(repoDir, sessionId);
    expect(status.data.task).toMatchObject({ status: 'framed', state_version: 1 });
    const audit = await auditShow(repoDir, sessionId);
    expect(audit.data.verification.valid).toBe(true);
    expect(transitionEvents(audit.data)).toHaveLength(1);
    expect(guardFailures(audit.data, 'STATE_VERSION_CONFLICT')).toHaveLength(1);

    const next = await sessionNext(repoDir, sessionId);
    expect(next.data).toMatchObject({
      contract_version: 3,
      lifecycle: { state: 'framed', state_version: 1 },
      audit: { status: 'valid', event_count: audit.data.count, root: audit.data.root },
    });
    const verified = await auditVerify(repoDir, sessionId, audit.data.root);
    expect(verified.data).toMatchObject({
      contract_version: 1,
      count: audit.data.count,
      root: audit.data.root,
      valid: true,
    });
  });
});

