    const replay = await bindControllerProofPlan(setup, 'controller:corrupt-proof-plan:1');
    await transitionLifecycle(replay.repoDir, replay.sessionId, 'implementing', 2, 'controller:corrupt-implement:2');
    await commitReplayFiles(replay, 'controlled corrupt-evidence implementation', initialReplayFiles());
    await transitionLifecycle(replay.repoDir, replay.sessionId, 'verifying', 3, 'controller:corrupt-verify:3');

    const wakes: WakeTrace[] = [];
    const initialGate = await runGateWake(replay, wakes, 'corrupt-run-initial-gate', 'RUN_MISSING_GATES');
    expectRequiredWorkBoundary(initialGate.next, 'PROOF_GATES_MISSING', 'RUN_MISSING_GATES', 'local_gate');
