describe('one-wake decision boundary', () => {
  function snapshot(input: {
    state: string;
    target: string | null;
    stateVersion?: number;
    fromState?: string;
    expectedVersion?: number;
    executable?: boolean;
    exhausted?: boolean;
    terminalReason?: string | null;
    requiredWork?: Array<{ code: string; description: string }>;
    guardFailures?: Array<{ code: string }>;
  }): Pick<
    SessionNextData,
    'lifecycle' | 'candidate' | 'guard_failures' | 'required_work' | 'repair_budget' | 'terminal_reason'
  > {
    const exhausted = input.exhausted ?? false;
    const stateVersion = input.stateVersion ?? 1;
    return {
      lifecycle: { state: input.state, state_version: stateVersion, history: [] },
      candidate:
        input.target === null
          ? null
          : {
              from_state: input.fromState ?? input.state,
              target_state: input.target,
              expected_state_version: input.expectedVersion ?? stateVersion,
              executable: input.executable ?? true,
            },
      guard_failures: input.guardFailures ?? [],
      required_work: input.requiredWork ?? [],
      repair_budget: {
        status: exhausted ? 'exhausted' : 'available',
        attempts_used: exhausted ? 3 : 0,
        limit: 3,
        remaining: exhausted ? 0 : 3,
        exhausted,
      },
      terminal_reason: input.terminalReason ?? null,
    };
  }

  it.each([
    ['ready_for_human', 'completed', false, null, 'hard_stop:ready_for_human'],
    ['blocked', 'reviewing', false, 'BLOCKED_REQUIRES_HUMAN_RECOVERY', 'hard_stop:blocked'],
    ['reviewing', 'repairing', true, null, 'hard_stop:repair_budget_exhausted'],
    ['completed', null, false, 'COMPLETED', 'hard_stop:completed'],
  ])('stops before a fresh candidate for %s', (state, target, exhausted, terminalReason, stopReason) => {
    const decision = selectOneWakeActionFromValidatedProjection(
      snapshot({
        state,
        target,
        exhausted,
        terminalReason,
      }),
    );
    expect(decision).toEqual({ decision: 'stop', actions: [], stopReason });
  });

  it('fails closed for unknown required work', () => {
    const decision = selectOneWakeActionFromValidatedProjection(
      snapshot({
        state: 'verifying',
        target: 'reviewing',
        executable: false,
        requiredWork: [{ code: 'FUTURE_UNRECOGNIZED_WORK', description: 'Not in the v3 allowlist' }],
        guardFailures: [{ code: 'FUTURE_UNRECOGNIZED_GUARD' }],
      }),
    );
    expect(decision).toEqual({
      decision: 'stop',
      actions: [],
      stopReason: 'unknown_required_work:FUTURE_UNRECOGNIZED_WORK',
    });
  });

  it.each(['SIGNED_CI_PROOF_REQUIRED', 'FUTURE_UNRECOGNIZED_GUARD'])(
    'fails closed when known required work is paired with %s',
    (guardCode) => {
      const decision = selectOneWakeActionFromValidatedProjection(
        snapshot({
          state: 'verifying',
          target: 'reviewing',
          executable: false,
          requiredWork: [{ code: 'RUN_MISSING_GATES', description: 'Known work under the wrong guard' }],
          guardFailures: [{ code: guardCode }],
        }),
      );
      expect(decision).toEqual({
        decision: 'stop',
        actions: [],
        stopReason: `guard_work_pair_mismatch:${guardCode}->RUN_MISSING_GATES`,
      });
    },
  );

  it.each([
    ['unknown lifecycle state', { state: 'future', target: null }, 'unknown_lifecycle_state:future'],
    ['unknown candidate target', { state: 'queued', target: 'future' }, 'unknown_candidate_target_state:future'],
    [
      'candidate from-state mismatch',
      { state: 'queued', target: 'framed', fromState: 'proof_ready' },
      'candidate_from_state_mismatch:proof_ready->queued',
    ],
    [
      'candidate state-version mismatch',
      { state: 'queued', target: 'framed', stateVersion: 2, expectedVersion: 1 },
      'candidate_state_version_mismatch:1->2',
    ],
  ] as const)('fails closed for %s', (_label, input, stopReason) => {
    expect(selectOneWakeActionFromValidatedProjection(snapshot(input))).toEqual({
      decision: 'stop',
      actions: [],
      stopReason,
    });
  });

