    expect(decisions[1]).toMatchObject({
      decision: 'local_gate',
      actions: [{ kind: 'local_gate', codeOrTarget: 'RUN_MISSING_GATES' }],
    });
    expect(decisions[2]?.decision).toBe('stop');
    expect(decisions[3]?.decision).toBe('stop');
    expect(decisions.every((decision) => decision.actions.length <= 1)).toBe(true);
  });

  it.each([
    ['canonical root changed', { repoRoot: '/tmp/other-worktree' }],
    ['branch changed', { branch: 'feat/other-work' }],
    ['HEAD changed', { headSha: 'b'.repeat(40) }],
    ['worktree became dirty', { worktreeClean: false }],
  ])('rejects an ambiguous transition retry when the Git %s', (_label, override) => {
    const retained: GitWakeSnapshot = {
      repoRoot: '/tmp/threadloop-task',
      branch: 'feat/issue-43-runner-contract',
      headSha: 'a'.repeat(40),
      worktreeClean: true,
    };
    expect(retainedTransitionGitSnapshotMatches(retained, { ...retained, ...override })).toBe(false);
  });

  it('allows an ambiguous transition retry only on the exact retained clean Git snapshot', () => {
    const retained: GitWakeSnapshot = {
      repoRoot: '/tmp/threadloop-task',
      branch: 'feat/issue-43-runner-contract',
      headSha: 'a'.repeat(40),
      worktreeClean: true,
    };
    expect(retainedTransitionGitSnapshotMatches(retained, { ...retained })).toBe(true);
    expect(retainedTransitionGitSnapshotMatches({ ...retained, worktreeClean: false }, retained)).toBe(false);
  });
});

